    void chooseApp(){if(!canAdd())return;Intent query=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER);java.util.List<android.content.pm.ResolveInfo> all=getPackageManager().queryIntentActivities(query,0);java.util.TreeMap<String,String> apps=new java.util.TreeMap<>(String.CASE_INSENSITIVE_ORDER);for(android.content.pm.ResolveInfo item:all){String p=item.activityInfo.packageName;if(!p.equals(getPackageName()))apps.put(item.loadLabel(getPackageManager()).toString()+"\n"+p,p);}if(apps.isEmpty()){toast("Không tìm thấy ứng dụng có thể mở");return;}String[] names=apps.keySet().toArray(new String[0]),packages=apps.values().toArray(new String[0]);new AlertDialog.Builder(this).setTitle("Chọn ứng dụng cần mở").setItems(names,(d,n)->{try{JSONObject step=new JSONObject().put("action","launch_app").put("label","Mở "+names[n].split("\n")[0]).put("package",packages[n]).put("delay",1500);StepDialogs.show(this,step,false,out->saveStep(out,-1),()->{},mode->{});}catch(Exception e){toast("Không tạo được bước mở ứng dụng");}}).setNegativeButton("Hủy",null).show();}
